# region: emit
def emit(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.lstrip('-').isdigit():
            out.append(int(s))
            return out
    return out

# region: intake
def intake(xs, offset=1):
    return [v + offset for v in xs]

# region: shape
def shape(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: render
def render(xs, offset=1):
    return [v + offset for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: digest
def digest(summary, name='gamma'):
    out = dict(summary)
    out['label'] = name.upper() if summary.get('n', 0) else 'EMPTY'
    return out

# region: run
def run(raw):
    return digest(fold(render(shape(intake(emit(raw))))))

